<?php require '../config/database.php';auth();$rows=$pdo->query('SELECT * FROM products WHERE quantity<=min_quantity ORDER BY quantity ASC')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>تنبيهات المخزون</h1><p>المنتجات التي وصلت للحد الأدنى أو أقل:</p><table><tr><th>المنتج</th><th>الكمية</th><th>الحد الأدنى</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=$r['quantity']?></td><td><?=$r['min_quantity']?></td></tr><?php endforeach;?></table></main>
